template:
% 参数由系统自动注入：\def\showline{1} \def\showquad{1} \def\showcube{1} \def\showsqrt{1} \def\showhyp{1} \def\showfixed{1}
% 固定视图：第一象限为主，第三象限留少量延伸
\pgfmathtruncatemacro{\xleft}{-2}
\pgfmathtruncatemacro{\xright}{5}
\pgfmathtruncatemacro{\ybottom}{-2}
\pgfmathtruncatemacro{\ytop}{5}
% 曲线到达视图边框的截断坐标（正、负向分别截断；宏名只能含字母）
\pgfmathsetmacro{\xqa}{sqrt(\ytop+0.3)}
\pgfmathsetmacro{\xqb}{sqrt(-\ybottom+0.3)}
\pgfmathsetmacro{\xca}{pow(\ytop+0.3,0.3333)}
\pgfmathsetmacro{\xcb}{pow(-\ybottom+0.3,0.3333)}
\pgfmathsetmacro{\xha}{1/(\ytop+0.3)}
\pgfmathsetmacro{\xhb}{1/(-\ybottom+0.3)}
\pgfmathsetmacro{\figscale}{6.5/(\xright-\xleft)}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系 =====
  \draw[->, thick] (\xleft-0.5,0) -- (\xright+0.6,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$}; % ===== y=1/x（双曲线，第一、三象限）=====
  \ifnum\showhyp>0
    \draw[thick, domain=\xha:\xright, samples=80, smooth] plot (\x, {1/\x});
    \draw[thick, domain=\xleft:-\xhb, samples=80, smooth] plot (\x, {1/\x});
    \node[font=\tiny, anchor=north west] at (3.5,0.8) {$y=\dfrac{1}{x}$};
  \fi
  % ===== y=x（直线，一、三象限）=====
  \ifnum\showline>0
    \draw[thick] (\xleft,\xleft) -- (\ytop,\ytop);
    \node[font=\tiny, anchor=north east] at (4.7,4.2) {$y=x$};
  \fi
  % ===== y=x²（偶函数，一、二象限）=====
  \ifnum\showquad>0
    \draw[thick, domain=-\xqa:\xqa, samples=80, smooth] plot (\x, {\x*\x});
    \node[font=\tiny, anchor=west] at (2.35,4.55) {$y=x^2$};
  \fi
  % ===== y=x³（奇函数，一、三象限）=====
  \ifnum\showcube>0
    \draw[thick, domain=-\xcb:\xca, samples=80, smooth] plot (\x, {\x*\x*\x});
    \node[font=\tiny, anchor=east] at (1.55,4.6) {$y=x^3$};
  \fi
  % ===== y=√x（仅第一象限）=====
  \ifnum\showsqrt>0
    \draw[thick, domain=0:\xright, samples=80, smooth] plot (\x, {sqrt(\x)});
    \node[font=\tiny, anchor=south west] at (3.4,2.4) {$y=\sqrt{x}$};
  \fi
  % ===== 公共定点 (1,1) =====
  \ifnum\showfixed>0
    \fill (1,1) circle [radius=\dotr pt];
    \node[font=\tiny, anchor=north] at (1.45,0.72) {$(1,1)$};
  \fi
\end{tikzpicture}
